This module does too much. Refactor it:
```javascript
// user-controller.js
import fs from 'fs';
import { sendEmail } from './mailer.js';
import db from './db.js';

export function registerUser(req, res) {
  const { email, password } = req.body;
  // validate
  if (!email || !password) return res.status(400).send('Missing fields');
  // hash password
  const hashed = crypto.createHash('sha256').update(password).digest('hex');
  // save to db
  const user = db.query('INSERT INTO users ...', [email, hashed]);
  // write to log file
  fs.writeFileSync('./logs/registrations.log', `${email}\n`, { flag: 'a' });
  // send welcome email
  sendEmail(email, 'Welcome!');
  res.json(user);
}
```

